    return '<div class="accordion accordion-flush" id="faq">'+''.join(f'<div class="accordion-item"><h3 class="accordion-header"><button class="accordion-button collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#faq-{i}" aria-expanded="false" aria-controls="faq-{i}">{q}</button></h3><div id="faq-{i}" class="accordion-collapse collapse" data-bs-parent="#faq"><div class="accordion-body text-body-secondary">{a}</div></div></div>' for i,(q,a) in enumerate(items))+'</div>'
